def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(
        r"\d+|[A-Z]+[0-9]*|<>|<=|>=|[+\-*/(),:=<>]"
    )
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "neg": 3,
    }
    cache = {}
    active = set()

    def parse(content):
        if not content.startswith("="):
            return ("number", int(content))

        tokens = token_pattern.findall(content[1:])
        values = []
        operators = []
        expect_operand = True
        i = 0

        def reduce_operator():
            op = operators.pop()
            if op == "neg":
                values.append(("neg", values.pop()))
            else:
                right = values.pop()
                left = values.pop()
                values.append(("binary", op, left, right))

        while i < len(tokens):
            token = tokens[i]

            if token.isdigit():
                values.append(("number", int(token)))
                expect_operand = False

            elif token in ("SUM", "MIN", "MAX", "IF"):
                operators.append(["(", token, 0])
                i += 1  # Consume the function's opening parenthesis.
                expect_operand = True

            elif token[0].isalpha():
                if i + 1 < len(tokens) and tokens[i + 1] == ":":
                    values.append(("range", token, tokens[i + 2]))
                    i += 2
                else:
                    values.append(("cell", token))
                expect_operand = False

            elif token == "(":
                operators.append(["(", None, 0])
                expect_operand = True

            elif token == ",":
                while isinstance(operators[-1], str):
                    reduce_operator()
                operators[-1][2] += 1
                expect_operand = True

            elif token == ")":
                while isinstance(operators[-1], str):
                    reduce_operator()
                _, function, commas = operators.pop()
                if function is not None:
                    count = commas + 1
                    args = values[-count:]
                    del values[-count:]
                    values.append(("function", function, args))
                expect_operand = False

            else:
                op = "neg" if token == "-" and expect_operand else token
                while operators and isinstance(operators[-1], str):
                    top = operators[-1]
                    if precedence[top] > precedence[op] or (
                        precedence[top] == precedence[op] and op != "neg"
                    ):
                        reduce_operator()
                    else:
                        break
                operators.append(op)
                expect_operand = True

            i += 1

        while operators:
            reduce_operator()
        return values[0]

    def arguments(args):
        for arg in args:
            if arg[0] != "range":
                yield arg
                continue

            first, last = arg[1], arg[2]
            left = min(ord(first[0]), ord(last[0]))
            right = max(ord(first[0]), ord(last[0]))
            top = min(int(first[1:]), int(last[1:]))
            bottom = max(int(first[1:]), int(last[1:]))

            for row in range(top, bottom + 1):
                for column in range(left, right + 1):
                    name = chr(column) + str(row)
                    if name in cells:
                        yield ("cell", name)

    def evaluate(name):
        stack = [("cell", name)]
        results = []

        while stack:
            task = stack.pop()
            kind = task[0]

            if kind == "cell":
                cell = task[1]
                if cell in cache:
                    results.append(cache[cell])
                elif cell in active:
                    results.append("#CYCLE!")
                elif cell not in cells:
                    results.append(0)
                else:
                    active.add(cell)
                    stack.append(("finish_cell", cell))
                    stack.append(("eval", parse(cells[cell])))

            elif kind == "finish_cell":
                cell = task[1]
                cache[cell] = results[-1]
                active.remove(cell)

            elif kind == "eval":
                node = task[1]
                node_kind = node[0]

                if node_kind == "number":
                    results.append(node[1])
                elif node_kind == "cell":
                    stack.append(("cell", node[1]))
                elif node_kind == "neg":
                    stack.append(("neg",))
                    stack.append(("eval", node[1]))
                elif node_kind == "binary":
                    stack.append(("binary_left", node[1], node[3]))
                    stack.append(("eval", node[2]))
                else:
                    function, args = node[1], node[2]
                    if function == "IF":
                        stack.append(("if", args[1], args[2]))
                        stack.append(("eval", args[0]))
                    else:
                        stack.append(("aggregate", function, iter(arguments(args)), None))

            elif kind == "neg":
                value = results.pop()
                results.append(value if isinstance(value, str) else -value)

            elif kind == "binary_left":
                left = results.pop()
                if isinstance(left, str):
                    results.append(left)
                else:
                    stack.append(("binary_right", task[1], left))
                    stack.append(("eval", task[2]))

            elif kind == "binary_right":
                op, left = task[1], task[2]
                right = results.pop()
                if isinstance(right, str):
                    results.append(right)
                elif op == "+":
                    results.append(left + right)
                elif op == "-":
                    results.append(left - right)
                elif op == "*":
                    results.append(left * right)
                elif op == "/":
                    if right == 0:
                        results.append("#DIV/0!")
                    else:
                        quotient = abs(left) // abs(right)
                        results.append(-quotient if (left < 0) != (right < 0) else quotient)
                elif op == "=":
                    results.append(int(left == right))
                elif op == "<>":
                    results.append(int(left != right))
                elif op == "<":
                    results.append(int(left < right))
                elif op == "<=":
                    results.append(int(left <= right))
                elif op == ">":
                    results.append(int(left > right))
                else:
                    results.append(int(left >= right))

            elif kind == "if":
                condition = results.pop()
                if isinstance(condition, str):
                    results.append(condition)
                else:
                    stack.append(("eval", task[1] if condition else task[2]))

            elif kind == "aggregate":
                function, iterator, accumulated = task[1:]
                next_arg = next(iterator, None)
                if next_arg is None:
                    results.append(0 if accumulated is None else accumulated)
                else:
                    stack.append(("aggregate_value", function, iterator, accumulated))
                    stack.append(("eval", next_arg))

            else:  # aggregate_value
                function, iterator, accumulated = task[1:]
                value = results.pop()
                if isinstance(value, str):
                    results.append(value)
                else:
                    if accumulated is None:
                        accumulated = value
                    elif function == "SUM":
                        accumulated += value
                    elif function == "MIN":
                        accumulated = min(accumulated, value)
                    else:
                        accumulated = max(accumulated, value)
                    stack.append(("aggregate", function, iterator, accumulated))

        return results.pop()

    for name in cells:
        if name not in cache:
            evaluate(name)

    return {name: cache[name] for name in cells}
